<script setup>
import AppShell from '../../Components/Ui/AppShell.vue'
import { computed, ref } from 'vue'
import { router, useForm } from '@inertiajs/vue3'
import { requestConfirmation } from '../../utils/confirmation'

const props = defineProps({ songs: Array, filters: Object, songStyles: Object, libraryImages: Array })
const query = ref(props.filters?.q ?? ''), modal = ref(false), editorTab = ref('metadata'), editorVersion = ref(null), generatedSheetUrl = ref(null), activeImageId = ref(null), draggedPartIndex = ref(null), interaction = ref(null), libraryModal = ref(false), libraryQuery = ref('')
const canvas = { width: 420, height: 595.28 }
const form = useForm({ title: '', composer: '', author: '', copyright_notice: '', age_group: '', topics: '', notes: '', version_name: '', lyrics: '', notation: '', chords: '', text_export_allowed: false, metadata_export_allowed: true, sheet: null })
const editor = useForm({ song: {}, name: '', language: 'de', parts: [], layout_data: { images: [] } }), imageForm = useForm({ images: [] })
const selectedImage = computed(() => editor.layout_data.images?.find(image => image.id === activeImageId.value) ?? null)
const canvasImages = computed(() => (editor.layout_data.images ?? []).filter(image => editorVersion.value?.images?.some(item => item.id === image.id)))
const filteredLibraryImages = computed(() => (props.libraryImages ?? []).filter(image => image.original_name.toLowerCase().includes(libraryQuery.value.toLowerCase())))
const songCredits = computed(() => {
    const author = (editor.song.author ?? '').trim(), composer = (editor.song.composer ?? '').trim(), copyright = (editor.song.copyright_notice ?? '').trim()
    let credit = author && composer && author.toLowerCase() === composer.toLowerCase() ? `Text & Musik: ${author}` : [author && `Text: ${author}`, composer && `Musik: ${composer}`].filter(Boolean).join(' / ')
    credit = copyright ? `${credit}${credit ? '. ' : ''}${copyright}` : credit
    const images = (editor.layout_data.images ?? []).map(image => (image.credits ?? '').trim()).filter(Boolean)
    return [credit, images.length ? `${images.length === 1 ? 'Bild:' : 'Bilder:'} ${images.join(' · ')}` : ''].filter(Boolean).join('\n')
})
const imageCredits = computed(() => (editor.layout_data.images ?? []).map(image => (image.credits ?? '').trim()).filter(Boolean))
const previewCredits = computed(() => [songCredits.value, imageCredits.value.length ? `${imageCredits.value.length === 1 ? 'Bild:' : 'Bilder:'} ${imageCredits.value.join(' · ')}` : ''].filter(Boolean).join('\n'))
const previewStyles = computed(() => ({ title: { fontFamily: props.songStyles?.title_font_family, fontSize: `${props.songStyles?.title_font_size ?? 24}px`, fontWeight: props.songStyles?.title_font_weight }, text: { fontFamily: props.songStyles?.text_font_family, fontSize: `${props.songStyles?.text_font_size ?? 14}px`, fontWeight: props.songStyles?.text_font_weight }, refrain: { fontFamily: props.songStyles?.refrain_font_family, fontSize: `${props.songStyles?.refrain_font_size ?? 14}px`, fontWeight: props.songStyles?.refrain_font_weight } }))
function search() { router.get('/lieder', { q: query.value }, { preserveState: true, replace: true }) }
function save() { form.post('/lieder', { forceFormData: true, onSuccess: () => { modal.value = false; form.reset() } }) }
function generatedSheetUrlFor(version, format = 'a5', cacheKey = (format === 'a4' ? version.generated_sheet_a4_path ?? version.generated_sheet_a4_at : version.generated_sheet_path ?? version.generated_sheet_at) ?? Date.now()) { const path = format === 'a4' ? version.generated_sheet_a4_path : version.generated_sheet_path; return path ? `/lieder/fassungen/${version.id}/liedblatt/erzeugt${format === 'a4' ? '/a4' : ''}?v=${encodeURIComponent(cacheKey)}` : null }
function imageUrl(imageId) { const image = editorVersion.value?.images?.find(item => item.id === imageId); const cacheKey = image?.updated_at ?? image?.id ?? Date.now(); return `/lieder/fassungen/${editorVersion.value.id}/bilder/${imageId}?v=${encodeURIComponent(cacheKey)}` }
function layoutForExistingImages(layoutData, images) { const imageIds = new Set((images ?? []).map(image => image.id)); return { ...(layoutData ?? {}), images: (layoutData?.images ?? []).filter(image => imageIds.has(image.id)) } }
function cleanLayoutData() { editor.layout_data = layoutForExistingImages(editor.layout_data, editorVersion.value?.images); return editor.layout_data }
function openEditor(version) { editorVersion.value = version; editorTab.value = 'metadata'; activeImageId.value = null; generatedSheetUrl.value = generatedSheetUrlFor(version); editor.defaults({ song: { title: version.song?.title ?? '', composer: version.song?.composer ?? '', author: version.song?.author ?? '', copyright_notice: version.song?.copyright_notice ?? '', age_group: version.song?.age_group ?? '', topics: version.song?.topics ?? '', notes: version.song?.notes ?? '' }, name: version.name, language: version.language ?? 'de', parts: (version.parts ?? []).map(part => ({ content: part.content, is_refrain: part.is_refrain })), layout_data: layoutForExistingImages(version.layout_data, version.images) }); editor.reset(); imageForm.reset() }
function refreshEditorVersion() { const updated = props.songs.flatMap(song => song.versions ?? []).find(version => version.id === editorVersion.value?.id); if (updated) { editorVersion.value = updated; cleanLayoutData() } }
function saveEditor() { cleanLayoutData(); editor.put(`/lieder/fassungen/${editorVersion.value.id}`, { preserveScroll: true, onSuccess: () => { refreshEditorVersion(); editorVersion.value = null } }) }
function uploadImages() { imageForm.post(`/lieder/fassungen/${editorVersion.value.id}/bilder`, { forceFormData: true, preserveState: true, preserveScroll: true, onSuccess: () => { refreshEditorVersion(); imageForm.reset() }, onError: errors => window.alert(Object.values(errors)[0] ?? 'Die Bilder konnten nicht hochgeladen werden.') }) }
function importLibraryImage(image) { router.post(`/lieder/fassungen/${editorVersion.value.id}/bilder/bibliothek`, { resource_id: image.id }, { preserveState: true, preserveScroll: true, onSuccess: () => { refreshEditorVersion() } }) }
async function deleteImage(image) { if (await requestConfirmation({ message: `„${image.original_name}“ wirklich löschen?` })) router.delete(`/lieder/fassungen/${editorVersion.value.id}/bilder/${image.id}`, { preserveState: true, preserveScroll: true, onSuccess: () => { editorVersion.value.images = editorVersion.value.images.filter(item => item.id !== image.id); editor.layout_data.images = editor.layout_data.images.filter(item => item.id !== image.id); if (activeImageId.value === image.id) activeImageId.value = null }, onError: errors => window.alert(Object.values(errors)[0] ?? 'Das Bild konnte nicht gelöscht werden.') }) }
function layoutFor(imageId) { return editor.layout_data.images?.find(image => image.id === imageId) }
function addImage(image) { if (!layoutFor(image.id)) editor.layout_data.images.push({ id: image.id, x: 20, y: 20, width: 100, height: 100, rotation: 0, flipX: false, flipY: false, credits: '' }); activeImageId.value = image.id }
function setImageCredits(imageId, value) { const layout = layoutFor(imageId); if (layout) layout.credits = value }
function flipImage(imageId, axis) { const layout = layoutFor(imageId); if (layout) layout[axis === 'x' ? 'flipX' : 'flipY'] = !layout[axis === 'x' ? 'flipX' : 'flipY'] }
function generateSheet() { cleanLayoutData(); editor.put(`/lieder/fassungen/${editorVersion.value.id}`, { preserveScroll: true, onSuccess: () => router.post(`/lieder/fassungen/${editorVersion.value.id}/liedblatt/erzeugen`, {}, { preserveScroll: true, onSuccess: () => { refreshEditorVersion(); generatedSheetUrl.value = generatedSheetUrlFor(editorVersion.value, Date.now()) }, onError: errors => window.alert(Object.values(errors)[0] ?? 'Das A5-Liedblatt konnte nicht erzeugt werden.') }), onError: errors => window.alert(Object.values(errors)[0] ?? 'Das Lied konnte nicht gespeichert werden.') }) }
function addPart() { editor.parts.push({ content: '', is_refrain: false }) }
function movePart(index, direction) { const target = index + direction; if (target < 0 || target >= editor.parts.length) return; const parts = [...editor.parts]; [parts[index], parts[target]] = [parts[target], parts[index]]; editor.parts = parts }
function startPartDrag(index, event) { draggedPartIndex.value = index; event.dataTransfer.effectAllowed = 'move' }
function dropPart(index) { if (draggedPartIndex.value === null || draggedPartIndex.value === index) return; const parts = [...editor.parts], [part] = parts.splice(draggedPartIndex.value, 1); parts.splice(index, 0, part); editor.parts = parts; draggedPartIndex.value = null }
function removePart(index) { editor.parts.splice(index, 1) }
function imageStyle(image) { return { left: 0, top: 0, width: `${image.width}px`, height: `${image.height}px`, transform: `rotate(${image.rotation}deg) scale(${image.flipX ? -1 : 1}, ${image.flipY ? -1 : 1})` } }
function beginInteraction(type, event, image, corner = null) { event.preventDefault(); activeImageId.value = image.id; interaction.value = { type, corner, image, startX: event.clientX, startY: event.clientY, x: image.x, y: image.y, width: image.width, height: image.height, rotation: image.rotation }; window.addEventListener('pointermove', continueInteraction); window.addEventListener('pointerup', endInteraction, { once: true }) }
function continueInteraction(event) { const state = interaction.value; if (!state) return; const dx = event.clientX - state.startX, dy = event.clientY - state.startY; if (state.type === 'move') { state.image.x = Math.max(0, Math.min(canvas.width - state.image.width, state.x + dx)); state.image.y = Math.max(0, Math.min(canvas.height - state.image.height, state.y + dy)); return } if (state.type === 'resize') { const west = state.corner.includes('w'), north = state.corner.includes('n'), width = Math.max(20, state.width + (west ? -dx : dx)), height = Math.max(20, state.height + (north ? -dy : dy)); state.image.width = width; state.image.height = height; state.image.x = Math.max(0, Math.min(canvas.width - width, west ? state.x + state.width - width : state.x)); state.image.y = Math.max(0, Math.min(canvas.height - height, north ? state.y + state.height - height : state.y)); return } const centerX = state.x + state.width / 2, centerY = state.y + state.height / 2; state.image.rotation = state.rotation + (Math.atan2(event.clientY - centerY - (state.startY - centerY), event.clientX - centerX - (state.startX - centerX)) * 180 / Math.PI) }
function endInteraction() { interaction.value = null; window.removeEventListener('pointermove', continueInteraction) }
function removeSelectedImage() { if (selectedImage.value) { editor.layout_data = { ...editor.layout_data, images: editor.layout_data.images.filter(image => image.id !== selectedImage.value.id) }; activeImageId.value = null } }
function handleImageKeydown(event) { if ((event.key === 'Delete' || event.key === 'Backspace') && selectedImage.value) { event.preventDefault(); removeSelectedImage() } }
window.addEventListener('keydown', handleImageKeydown)
async function removeSong(song) { if (await requestConfirmation({ message: `„${song.title}“ wirklich löschen?` })) router.delete(`/lieder/${song.id}`) }
</script>

<template>
    <AppShell>
        <template #toolbar><button class="btn btn-sm btn-primary" type="button" @click="modal = true"><i class="bi bi-plus-lg me-1"></i>Lied anlegen</button></template>
        <div class="container-full px-3 py-4"><h1 class="h2 mb-4">Liedersammlung</h1><form class="d-flex gap-2 mb-3" @submit.prevent="search"><input v-model="query" class="form-control" placeholder="Lieder durchsuchen"><button class="btn btn-outline-secondary">Suchen</button></form><div class="list-group"><div v-for="song in songs" :key="song.id" class="list-group-item song-index-row"><div class="song-index-title"><strong class="text-truncate">{{ song.title }}</strong></div><div class="song-index-credits small text-muted"><span>{{ [song.author, song.composer].filter(Boolean).join(' · ') || 'Keine Credits' }}</span><span v-if="song.versions.some(version => version.sheet)" class="d-block text-success"><i class="bi bi-file-earmark-pdf"></i> Liedblatt vorhanden</span></div><div class="song-index-actions"><template v-for="version in song.versions" :key="version.id"><a v-if="version.generated_sheet_path" class="btn btn-sm btn-outline-success" :href="generatedSheetUrlFor(version, 'a5')" download title="A5-Lied herunterladen"><i class="bi bi-download me-1"></i>A5</a><a v-if="version.generated_sheet_a4_path" class="btn btn-sm btn-outline-success" :href="generatedSheetUrlFor(version, 'a4')" download title="A4-Lied herunterladen"><i class="bi bi-download me-1"></i>A4</a><button class="btn btn-sm btn-outline-secondary" type="button" title="Lied bearbeiten" @click="openEditor(version)"><i class="bi bi-pencil"></i><span class="visually-hidden">Lied bearbeiten</span></button></template><button v-if="song.can_delete" class="btn btn-sm btn-outline-danger" type="button" title="Lied löschen" @click="removeSong(song)"><i class="bi bi-trash"></i><span class="visually-hidden">Lied löschen</span></button></div></div><p v-if="!songs.length" class="text-muted">Noch keine Lieder vorhanden.</p></div></div>
        <div v-if="modal" class="roo-modal-backdrop" @click.self="modal = false"><form class="roo-modal card" @submit.prevent="save"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5">Lied anlegen</h2><button type="button" class="btn-close" @click="modal = false"></button></div><label class="form-label">Titel</label><input v-model="form.title" class="form-control" required><div class="row g-2"><div class="col-md-6"><label class="form-label mt-2">Text</label><input v-model="form.author" class="form-control"></div><div class="col-md-6"><label class="form-label mt-2">Musik</label><input v-model="form.composer" class="form-control"></div></div><label class="form-label mt-2">Fassung</label><input v-model="form.version_name" class="form-control" required><label class="form-label mt-2">Vorhandenes A5-Liedblatt (PDF)</label><input class="form-control" type="file" accept="application/pdf" @change="form.sheet = $event.target.files?.[0] ?? null"><button class="btn btn-primary mt-3" :disabled="form.processing">Speichern</button></div></form></div>
        <div v-if="editorVersion" class="roo-modal-backdrop" @click.self="editorVersion = null"><section class="roo-modal roo-modal-song-editor card" role="dialog" aria-modal="true" aria-label="Lied bearbeiten"><div class="card-body d-flex flex-column"><div class="d-flex justify-content-between align-items-center"><h2 class="h5 mb-0">Lied bearbeiten</h2><button class="btn-close" type="button" @click="editorVersion = null"></button></div><ul class="nav nav-tabs mt-3 mb-3"><li class="nav-item"><button class="nav-link" :class="{ active: editorTab === 'metadata' }" type="button" @click="editorTab = 'metadata'">Metadaten</button></li><li class="nav-item"><button class="nav-link" :class="{ active: editorTab === 'liedblatt' }" type="button" @click="editorTab = 'liedblatt'">Liedblatt</button></li></ul><div v-if="editorTab === 'metadata'" class="row g-3 editor-tab-content"><div class="col-md-8"><label class="form-label">Titel</label><input v-model="editor.song.title" class="form-control" required></div><div class="col-md-4"><label class="form-label">Sprache</label><input v-model="editor.language" class="form-control"></div><div class="col-md-6"><label class="form-label">Text</label><input v-model="editor.song.author" class="form-control"></div><div class="col-md-6"><label class="form-label">Musik</label><input v-model="editor.song.composer" class="form-control"></div><div class="col-md-6"><label class="form-label">Fassungsname</label><input v-model="editor.name" class="form-control" required></div><div class="col-md-6"><label class="form-label">Altersgruppe</label><input v-model="editor.song.age_group" class="form-control"></div><div class="col-md-6"><label class="form-label">Themen</label><input v-model="editor.song.topics" class="form-control"></div><div class="col-md-6"><label class="form-label">Rechtehinweis</label><input v-model="editor.song.copyright_notice" class="form-control"></div><div class="col-12"><label class="form-label">Notizen</label><textarea v-model="editor.song.notes" class="form-control" rows="5"></textarea></div></div><div v-else class="songbook-editor-grid row g-3 editor-tab-content overflow-hidden"><div class="col-lg-4 songbook-editor-column song-parts-scroll"><div class="d-flex justify-content-between align-items-center"><h3 class="h6 mb-0">Liedteile</h3><button class="btn btn-sm btn-outline-primary" type="button" @click="addPart">Teil hinzufügen</button></div><div v-for="(part, index) in editor.parts" :key="index" class="border rounded p-2 mt-2" draggable="true" @dragstart="startPartDrag(index, $event)" @dragover.prevent @drop="dropPart(index)"><div class="d-flex align-items-center gap-1"><i class="bi bi-grip-vertical text-muted"></i><label class="form-check small flex-grow-1 mb-0"><input v-model="part.is_refrain" class="form-check-input" type="checkbox"> Kehrvers</label><button class="btn btn-sm btn-link p-0" type="button" :disabled="index === 0" @click="movePart(index, -1)"><i class="bi bi-chevron-up"></i></button><button class="btn btn-sm btn-link p-0" type="button" :disabled="index === editor.parts.length - 1" @click="movePart(index, 1)"><i class="bi bi-chevron-down"></i></button><button class="btn btn-sm btn-link text-danger p-0" type="button" title="Teil löschen" @click="removePart(index)"><i class="bi bi-trash"></i></button></div><textarea v-model="part.content" class="form-control mt-2" rows="6" placeholder="Text"></textarea></div></div><div class="col-lg-5 songbook-editor-column song-preview-pane"><h3 class="h6">A5-Vorschau</h3><div class="song-canvas border bg-white position-relative" @click="activeImageId = null"><div class="p-3"><h4 class="song-preview-title" :style="previewStyles.title">{{ editor.song.title }}</h4><p v-if="songCredits" class="song-preview-credits">{{ songCredits }}</p><section v-for="(part, index) in editor.parts" :key="index" class="song-preview-part" :style="part.is_refrain ? previewStyles.refrain : previewStyles.text">{{ part.content }}</section></div><div class="song-hole-hints" aria-hidden="true"><span class="song-hole-hint"></span><span class="song-hole-hint"></span></div><div v-for="image in canvasImages" :key="image.id" class="song-image-selection" :class="{ selected: activeImageId === image.id }" :style="{ left: `${image.x}px`, top: `${image.y}px`, width: `${image.width}px`, height: `${image.height}px` }" @pointerdown.stop="beginInteraction('move', $event, image)"><img :src="imageUrl(image.id)" :style="imageStyle(image)" alt=""><button v-for="corner in ['nw', 'ne', 'sw', 'se']" :key="corner" class="image-handle resize-handle" :class="corner" type="button" @pointerdown.stop="beginInteraction('resize', $event, image, corner)"></button><button class="image-handle rotate-handle" type="button" @pointerdown.stop="beginInteraction('rotate', $event, image)"></button></div><div v-if="imageCredits.length" class="song-preview-image-credits"><strong>{{ imageCredits.length === 1 ? 'Bild:' : 'Bilder:' }}</strong> {{ imageCredits.join(' · ') }}</div></div></div><div class="col-lg-3 songbook-editor-column song-image-column"><h3 class="h6">Bilder</h3><label class="form-label">Hochladen</label><input class="form-control" type="file" accept="image/*" multiple @change="imageForm.images = [...$event.target.files]"><div class="d-flex gap-2 mt-2"><button class="btn btn-sm btn-outline-secondary" type="button" :disabled="imageForm.processing || !imageForm.images.length" @click="uploadImages">Bilder hochladen</button><button class="btn btn-sm btn-outline-primary" type="button" @click="libraryModal = true"><i class="bi bi-images me-1"></i>Bild aus Bibliothek wählen</button></div><h4 class="h6 mt-4">Hochgeladene Bilder</h4><div v-for="image in editorVersion.images" :key="image.id" class="small mt-2"><div class="d-flex gap-1"><button class="btn btn-sm btn-outline-secondary flex-grow-1 text-start" type="button" @click="addImage(image)">{{ image.original_name }}</button><button class="btn btn-sm btn-outline-danger" type="button" title="Bild löschen" @click="deleteImage(image)"><i class="bi bi-trash"></i></button></div><template v-if="layoutFor(image.id)"><input class="form-control form-control-sm mt-1" :value="layoutFor(image.id).credits" placeholder="Bild-Credits" @input="setImageCredits(image.id, $event.target.value)"><div class="d-flex gap-1 mt-1"><button class="btn btn-sm btn-outline-secondary" type="button" @click="flipImage(image.id, 'x')">↔ Spiegeln</button><button class="btn btn-sm btn-outline-secondary" type="button" @click="flipImage(image.id, 'y')">↕ Spiegeln</button></div></template></div></div></div><div class="d-flex justify-content-end gap-2 mt-4"><button class="btn btn-outline-secondary" type="button" @click="editorVersion = null">Abbrechen</button><button class="btn btn-primary" type="button" :disabled="editor.processing" @click="saveEditor">Speichern</button></div></div></section></div>

        <button v-if="editorVersion && editorTab === 'liedblatt' && selectedImage" class="song-image-remove-launcher btn btn-danger btn-sm" type="button" @click="removeSelectedImage"><i class="bi bi-trash me-1"></i>Bild aus Vorschau entfernen</button>
        <div v-if="libraryModal" class="roo-modal-backdrop roo-library-modal-backdrop" @click.self="libraryModal = false"><section class="roo-modal card roo-library-image-modal"><div class="card-body"><div class="d-flex justify-content-between align-items-center"><h2 class="h5 mb-0">Bild aus Bibliothek wählen</h2><button class="btn-close" type="button" @click="libraryModal = false"></button></div><input v-model="libraryQuery" class="form-control mt-3" placeholder="Bilder suchen"><div class="list-group mt-3"><div v-for="image in filteredLibraryImages" :key="image.id" class="list-group-item d-flex align-items-center gap-2"><span class="flex-grow-1 text-truncate">{{ image.original_name }}</span><button class="btn btn-sm btn-primary" type="button" @click="importLibraryImage(image)">Übernehmen</button></div><p v-if="!filteredLibraryImages.length" class="small text-muted mt-2">Keine passenden Bilder gefunden.</p></div></div></section></div>
    </AppShell>
</template>
